/**
 * tests/tenant-paper-identity-2026-11-06.test.js — CRM audit 2026-11-06,
 * tenant-brand pass (OR-F01/F02, ED-F13/F14/F15, VW-F54, CU-F11).
 *
 * 1. "Generated by NBD Pro" — the SaaS product's name — printed on customer
 *    paper: the generic renderer (Permit Application has no renderer of its own),
 *    the finalized estimate, the classic estimate export, the scope/supplement
 *    sheets, and the body of the email sent to the homeowner. Rendered proof
 *    first (the permit renders for a non-NBD tenant), then the absence checks.
 * 2. Pre-flight prefill literals carried NBD's identity (company name / phone /
 *    email, "NBD Inspector", "Joe Deal") onto every tenant's documents. NBD keeps
 *    them byte-identical; another tenant gets its own values or a blank.
 * 3. Retired brand colours hide as RGB triplets ([30, 58, 110] = #1E3A6E,
 *    rgba(232,114,12,…) = #E8720C) that a hex grep never sees. The scan has a
 *    planted positive control so it cannot pass by matching nothing.
 *
 * Zero deps. Run: node tests/tenant-paper-identity-2026-11-06.test.js
 */
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const JS = path.join(ROOT, 'docs', 'pro', 'js');
let passed = 0, failed = 0;
function ok(name, cond, detail) {
  if (cond) { passed++; console.log('  ✓ ' + name); }
  else { failed++; console.log('  ✗ ' + name + (detail ? ' — ' + detail : '')); }
}
const read = (f) => fs.readFileSync(path.join(JS, f), 'utf8');

// ── 1. Product name on customer paper ──────────────────────────────────────
console.log('NO PRODUCT NAME ON CUSTOMER PAPER');
{
  const brand = { legalName: 'Test Roofing LLC', displayName: 'Test Roofing', colors: {}, contact: { phone: '(555) 010-0100' } };
  const win = { _brand: () => brand, _isNbdPlatformTenant: () => false };
  win.window = win;
  const noop = () => ({ style: {}, appendChild() {}, setAttribute() {}, addEventListener() {} });
  const sandbox = { window: win, console: { log() {}, warn() {}, error() {} }, setTimeout, clearTimeout, Date, Math, JSON,
    document: { addEventListener() {}, getElementById() { return null; }, querySelector() { return null; }, createElement: noop, body: noop() } };
  vm.runInNewContext(read('document-generator.js'), sandbox, { filename: 'document-generator.js' });
  vm.runInNewContext(read('document-generator-templates.js'), sandbox, { filename: 'document-generator-templates.js' });
  let html = '';
  try { html = win.NBDDocGen.getHTML('permit', { customerName: 'Test Homeowner 01', address: '100 Test St', _isBlankPreview: true, companyProfile: {} }) || ''; }
  catch (e) { html = 'RENDER_ERROR ' + e.message; }
  ok('the permit application renders for a non-NBD tenant (positive control)', html.length > 400 && html.indexOf('RENDER_ERROR') !== 0 && /Test Roofing/.test(html), html.slice(0, 80));
  ok('…and does not print "NBD Pro"', !/NBD Pro/.test(html));
  // OR-F03: renderer <style> blocks shipped CSS comments (internal notes) into
  // the customer's saved HTML; getHTML strips them.
  const styles = (html.match(/<style\b[\s\S]*?<\/style>/gi) || []).join('\n');
  ok('…its styles survive (positive control)', styles.length > 200);
  ok('…with no CSS comments in any <style> block', !/\/\*[\s\S]*?\*\//.test(styles), (styles.match(/\/\*[\s\S]{0,60}/) || [''])[0]);
}
for (const f of ['document-generator.js', 'estimate-finalization.js', 'estimates.js', 'maps-routing.js', 'nbd-doc-viewer.js']) {
  const src = read(f);
  ok(f + ' has no "Generated by NBD Pro" line', src.length > 1000 && !/Generated by NBD Pro/.test(src));
}
{
  const src = read('estimates.js');
  ok('classic estimate export resolves its wordmark/footer from the tenant brand', /_isNbdPlatformTenant/.test(src) && /\$\{_tMark\}/.test(src) && /\$\{_tFoot\}/.test(src));
}

// ── 2. Pre-flight identity literals ────────────────────────────────────────
console.log('PRE-FLIGHT PREFILL USES THE TENANT\'S IDENTITY');
function preflight(isNbd, brand) {
  const win = { _brand: () => brand };
  if (isNbd !== undefined) win._isNbdPlatformTenant = () => isNbd;
  win.window = win;
  const sandbox = { window: win, console: { log() {}, warn() {}, error() {} }, Date, Math, JSON,
    document: { addEventListener() {}, getElementById() { return null; }, querySelector() { return null; }, querySelectorAll() { return []; }, createElement() { return { style: {}, appendChild() {}, setAttribute() {}, addEventListener() {} }; } } };
  vm.runInNewContext(read('doc-preflight.js'), sandbox, { filename: 'doc-preflight.js' });
  const r = win.DocPreflight._resolveFieldValue;
  return (lit, key) => r({ key: key || 'k', source: 'literal:' + lit, persist: 'document' }, { lead: {}, overrides: {} });
}
{
  const nbd = preflight(true, { legalName: 'No Big Deal Home Solutions' });
  ok('NBD keeps "NBD Inspector" (byte-identical)', nbd('NBD Inspector', 'inspectorName') === 'NBD Inspector');
  ok('NBD keeps its company name', nbd('No Big Deal Home Solutions', 'companyName') === 'No Big Deal Home Solutions');
  const t = preflight(false, { legalName: 'Test Roofing LLC', contact: { phone: '(555) 010-0100', email: 'office@test.example' } });
  ok('another tenant: inspector is "<its name> Inspector"', t('NBD Inspector', 'inspectorName') === 'Test Roofing LLC Inspector', t('NBD Inspector', 'inspectorName'));
  ok('another tenant: company name / phone / email are its own', t('No Big Deal Home Solutions') === 'Test Roofing LLC' && t('(859) 420-7382') === '(555) 010-0100' && t('info@nobigdealwithjoedeal.com') === 'office@test.example');
  ok('another tenant: "Joe Deal" is left blank for the rep', t('Joe Deal', 'authorizedBy') === '');
  ok('unrelated literals pass through unchanged (control)', t('5-7 business days') === '5-7 business days');
  const unknown = preflight(undefined, {});
  ok('identity unknown (check not loaded) keeps the literal, as before', unknown('NBD Inspector') === 'NBD Inspector');
}

// ── 3. Retired colours as RGB triplets ─────────────────────────────────────
console.log('NO RETIRED BRAND COLOURS AS RGB TRIPLETS IN docs/pro');
{
  const RETIRED = ['E8720C', 'DA6A05', 'B85400', 'A64B00', 'C45E08', 'F08030', 'FFAF66', '1E3A6E', '1A3A5C', '1A1A2E', '142A52', '1F3A6D', 'F36F21'];
  const res = RETIRED.map((h) => {
    const [r, g, b] = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
    return [h, new RegExp('[\\[(]\\s*' + r + '\\s*,\\s*' + g + '\\s*,\\s*' + b + '\\b')];
  });
  const scan = (text) => res.filter(([, re]) => re.test(text)).map(([h]) => h);
  ok('scanner catches a planted [30, 58, 110] and rgba(232,114,12,.1) (positive control)', scan('x || [30, 58, 110]; y{background:rgba(232,114,12,.1)}').join() === 'E8720C,1E3A6E');
  const files = execFileSync('git', ['ls-files', 'docs/pro'], { cwd: ROOT, encoding: 'utf8' }).split('\n').filter((f) => /\.(js|css|html)$/.test(f));
  ok('docs/pro file list is non-empty (positive control)', files.length > 100, String(files.length));
  const hits = [];
  for (const f of files) { const h = scan(fs.readFileSync(path.join(ROOT, f), 'utf8')); if (h.length) hits.push(f + ':' + h.join('/')); }
  ok('no retired colour triplet anywhere in docs/pro', hits.length === 0, hits.join(', '));
}

console.log('\n' + passed + ' passed, ' + failed + ' failed');
process.exit(failed ? 1 : 0);
